def solve():
    n = int(input())
    segments = []

    for _ in range(n):
        l, r = map(int, input().split())
        segments.append((l, r))

    # Sort segments by left endpoint
    segments.sort()

    # Coordinate compression for right endpoints
    unique_rs = sorted(set(r for l, r in segments))
    compress = {r: i+1 for i, r in enumerate(unique_rs)}

    # Fenwick Tree implementation
    class FenwickTree:
        def __init__(self, size):
            self.size = size
            self.tree = [0] * (self.size + 1)

        def update(self, index, delta=1):
            while index <= self.size:
                self.tree[index] += delta
                index += index & -index

        def query(self, index):
            res = 0
            while index > 0:
                res += self.tree[index]
                index -= index & -index
            return res

    ft = FenwickTree(len(unique_rs))

    # Iterate from right to left by left endpoint
    result = [0] * n

    for i in range(n - 1, -1, -1):
        l, r = segments[i]
        # Find how many segments have right < current right
        count = ft.query(compress[r] - 1)
        result[i] = count
        ft.update(compress[r])

    for ans in result:
        print(ans)

solve()
