    a, b = map(int, input().split())
    pairs.append((a, b))

# For each candidate x, check if there exists y > x such that all pairs contain x or y
def solve():
    for x in range(1, n + 1):
        # Find all numbers that appear in pairs NOT containing x
        bad_numbers = set()
        for pair in pairs:
            if pair[0] != x and pair[1] != x:
                bad_numbers.add(pair[0])
                bad_numbers.add(pair[1])

        if not bad_numbers:
            print("YES")
            return

        # Check if there exists y > x in bad_numbers
        for y in bad_numbers:
            if y > x:
                print("YES")
                return

    print("NO")

solve()
