for _ in range(m):
    a, b = map(int, input().split())
    pairs.append((a, b))

# For each candidate x, check if there exists y > x such that all pairs contain x or y
def solve():
    for x in range(1, n + 1):
        # Find all numbers that appear in pairs NOT containing x
        # And find the intersection of these numbers across all such pairs
        common_set = None

        for pair in pairs:
            if pair[0] != x and pair[1] != x:
                # This pair doesn't contain x
                # Find the set of numbers in this pair
                pair_set = {pair[0], pair[1]}

                if common_set is None:
                    common_set = pair_set.copy()
                else:
                    common_set &= pair_set

                # If common_set becomes empty, we can stop early
                if not common_set:
                    break

        if common_set is None:
            # All pairs contain x, so any y > x works
            print("YES")
            return

        # Check if there exists y > x in common_set
        for y in common_set:
            if y > x:
                print("YES")
                return

    print("NO")

solve()
