def smallest_prime_factor(n):
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n

def count_steps(n):
    count = 0
    while n > 1:
        spf = smallest_prime_factor(n)
        n -= spf
        count += 1
    return count

n = int(input())
print(count_steps(n))
