def solve():
    n = int(input())
    facing = list(map(int, input().split()))

    # cows facing right (index i, sees cows i+1 to n)
    right = []
    # cows facing left (index i, sees cows 1 to i-1)
    left = []

    for i in range(n):
        if facing[i] == 1:
            right.append(i + 1)  # 1-indexed
        else:
