    # Track which cows have been milked
    milked = [False] * (n + 1)

    # Milk right-facing cows first
    for cow in reversed(right):
        milked[cow] = True

        # Count un-milked cows that see this cow
        if facing[cow - 1] == 1:  # facing right
            # sees cows from cow+1 to n
            for j in range(cow + 1, n + 1):
                if not milked[j]:
                    total_loss += 1
        else:  # facing left
            # sees cows from 1 to cow-1
            for j in range(1, cow):
                if not milked[j]:
                    total_loss += 1

    # Milk left-facing cows
    for cow in left:
        milked[cow] = True

        # Count un-milked cows that see this cow
        if facing[cow - 1] == 1:  # facing right
            # sees cows from cow+1 to n
            for j in range(cow + 1, n + 1):
                if not milked[j]:
                    total_loss += 1
        else:  # facing left
            # sees cows from 1 to cow-1
            for j in range(1, cow):
                if not milked[j]:
                    total_loss += 1

    print(total_loss)

