    n = int(input())
    count = {}
    max_k = -1

    for _ in range(n):
        k, a = map(int, input().split())
        count[k] = a
        if k > max_k:
            max_k = k

    # Process from smallest to largest
    for k in range(max_k + 1):
        if count.get(k, 0) > 0:
            needed = (count[k] + 3) // 4  # ceil division
            count[k+1] = count.get(k+1, 0) + needed
            count[k] = 0

    # Find the smallest size with boxes left
    for p in range(max_k + 2):
        if count.get(p, 0) > 0:
            print(p)
            return

