import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    sequences = data[1:1+n]

    opening_counts = {}  # balance -> count of opening sequences
    opening_mins = {}
    closing_counts = {}  # balance -> count of closing sequences
    closing_mins = {}

    for seq in sequences:
        # Calculate balance and min balance
        balance = 0
        min_balance = 0
        for c in seq:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            min_balance = min(min_balance, balance)

        if balance > 0:
            # Opening sequence
            opening_counts[balance] = opening_counts.get(balance, 0) + 1
            opening_mins[balance] = min(opening_mins.get(balance, float('inf')), min_balance)
        elif balance < 0:
            # Closing sequence
            closing_counts[-balance] = closing_counts.get(-balance, 0) + 1
            closing_mins[-balance] = min(closing_mins.get(-balance, float('inf')), min_balance)
        else:
            # Balanced sequence, can't be used for pairing
            pass

    pairs = 0

    # For each opening sequence, try to pair with closing sequences
    for b in opening_counts:
        if -b in closing_counts:
            # We need to pair opening with balance b with closing with balance -b
            # But we also need to ensure that when concatenated, min balance ≥ 0
            # And both sequences must have min balance ≥ 0

            # Find the minimum balance in opening sequences with this balance
            min_opening = opening_mins[b]
            # Find the minimum balance in closing sequences with this balance
            min_closing = closing_mins[-b]

            # When concatenated, the minimum balance is min(min_opening, balance_of_opening + min_closing)
            # But balance_of_opening = b, and balance_of_closing = -b, so total balance = 0
            min_combined = min(min_opening, b + min_closing)

            if min_combined >= 0:
                pairs += opening_counts[b] * closing_counts[-b]

    print(pairs)

if __name__ == '__main__':
    solve()
