import sys

def kosaraju(n, adj):
    visited = [False] * (n + 1)
    order = []

    def dfs1(u):
        stack = [u]
        visited[u] = True
        while stack:
            v = stack.pop()
            for nei in adj[v]:
                if not visited[nei]:
                    visited[nei] = True
                    stack.append(nei)
            order.append(v)

    for u in range(1, n + 1):
        if not visited[u]:
            dfs1(u)

    # Reverse graph
    rev_adj = [[] for _ in range(n + 1)]
    for u in range(1, n + 1):
        for v in adj[u]:
            rev_adj[v].append(u)

    visited = [False] * (n + 1)
    comp = [0] * (n + 1)
    cur = 0

    def dfs2(u, cur):
        stack = [u]
        visited[u] = True
        comp[u] = cur
        while stack:
            v = stack.pop()
            for nei in rev_adj[v]:
                if not visited[nei]:
                    visited[nei] = True
                    comp[nei] = cur
                    stack.append(nei)

    for u in reversed(order):
        if not visited[u]:
            cur += 1
            dfs2(u, cur)
    return comp, cur

