import bisect

def longest_increasing_subsequence_length(arr):
    """Find length of longest increasing subsequence in O(n log n)."""
    dp = []  # tails of increasing subsequences
    for num in arr:
        idx = bisect.bisect_left(dp, num)
        if idx == len(dp):
            dp.append(num)
        else:
            dp[idx] = num
    return len(dp)

n = int(input())
a = list(map(int, input().split()))

# We need the length of longest increasing subsequence in array a
# The elements of a are positions in 1..n

lis_length = longest_increasing_subsequence_length(a)
print(n - lis_length)
