        if line.strip() != "":
            s2 = int(line.strip())
            break

    # Ask about a specific subsegment that excludes s2
    # The example uses ? 4 5 when s2 is 3
    print(f"? {s2 + 1} {n}")
    sys.stdout.flush()

    # Get the answer for the subsegment
    while True:
        line = sys.stdin.readline()
