# Sizes: S, M, L, XL, XXL, XXXL (indices 0 to 5)
sizes = ['S', 'M', 'L', 'XL', 'XXL', 'XXXL']
size_idx = {size: i for i, size in enumerate(sizes)}

# Parse input
shirt_counts = list(map(int, input().split()))
n = int(input())

# Track which participants requested which sizes
participant_requests = []
for _ in range(n):
    line = input().strip()
    participant_requests.append(line)

# Parse and count demands
fixed_demands = [0] * 6  # Participants who want exactly one size
flexible_demands = []    # Participants who want two neighboring sizes

for request in participant_requests:
    if ',' in request:
        # Flexible choice
        from_size, to_size = request.split(',')
        flexible_demands.append((from_size, to_size))
    else:
        # Fixed choice
        size = request
        fixed_demands[size_idx[size]] += 1

# Check if we can fulfill fixed demands
for i in range(6):
    if fixed_demands[i] > shirt_counts[i]:
        print("NO")
        exit()

# Allocate fixed demands
remaining = [shirt_counts[i] - fixed_demands[i] for i in range(6)]

# Now handle flexible demands
assignment = []

for i, (from_size, to_size) in enumerate(flexible_demands):
    from_idx = size_idx[from_size]
    to_idx = size_idx[to_size]

    # Try to assign this participant
    if remaining[from_idx] > 0:
        assignment.append(from_size)
        remaining[from_idx] -= 1
    elif remaining[to_idx] > 0:
        assignment.append(to_size)
        remaining[to_idx] -= 1
    else:
        # We need to find a matching

        # This is a bipartite matching problem
        # Create a bipartite graph between participants and sizes
        # But we need to be more clever

        # We can try to reallocate t-shirts from the other end
        # First, try to use the larger size
        if to_idx > from_idx:
            if remaining[to_idx] > 0:
                assignment.append(to_size)
                remaining[to_idx] -= 1
            elif remaining[from_idx] > 0:
                assignment.append(from_size)
                remaining[from_idx] -= 1
            else:
                print("NO")
                exit()
        else:
            if remaining[from_idx] > 0:
                assignment.append(from_size)
                remaining[from_idx] -= 1
            elif remaining[to_idx] > 0:
                assignment.append(to_size)
                remaining[to_idx] -= 1
            else:
                print("NO")
                exit()

# Now, verify if we have a valid assignment
valid = True
for i in range(n):
    request = participant_requests[i]
    if ',' in request:
        from_size, to_size = request.split(',')
        if assignment[i] == from_size or assignment[i] == to_size:
            continue
        valid = False
        break
    else:
        if assignment[i] != request:
            valid = False
            break

if not valid:
    print("NO")
else:
    print("YES")
    for size in assignment:
        print(size)
