            # Both cells in column i are unblocked
            # Check if either column i-1 or column i+1 has 0 unblocked cells
            if (i > 0 and (not grid[0][i-1] and not grid[1][i-1])) or (i < n-1 and (not grid[0][i+1] and not grid[1][i+1])):
