def is_square(points):
    if len(points) != 4:
        return False

    # Sort by distance from the first point
    points = sorted(points, key=lambda p: p[0]**2 + p[1]**2)
    d = [p[0]**2 + p[1]**2 for p in points]

    # For a square: 0, a, 2a, 4a (distances squared)
    # Check if this pattern exists
    if d[0] == 0 and d[1] == d[3] and d[2] == 2 * d[1] and d[3] == 4 * d[1]:
        return True

    # Check if we have a different pattern
    if d[1] == 0 and d[2] == d[3] and d[3] == 2 * d[0] and d[0] == d[2] / 2:
        return True

    return False

def rotate(p, a, b):
    x, y = p
    return (a - y + b, b + x - a)

def solve():
    n = int(input())

    results = []

    for _ in range(n):
        points = []
        for _ in range(4):
            x, y, a, b = map(int, input().split())
            points.append(((x, y), a, b))

        # Try all possible rotation counts
        min_moves = -1

        # Check all possible rotation combinations
        # We can rotate 0-4 times for each mole
        # For simplicity, just try all 16 combinations (2^4)
        for i in range(16):
            # Rotate moles according to bits in i
            rotated = []
            for idx, (p, a, b) in enumerate(points):
                moves = i >> idx & 1
                rot_p = p
                for _ in range(moves):
                    rot_p = rotate(rot_p, a, b)
                rotated.append(rot_p)

            # Check if we have a square
            if is_square(rotated):
                moves_count = bin(i).count('1')
                if min_moves == -1 or moves_count < min_moves:
                    min_moves = moves_count

        results.append(str(min_moves))

    print('\n'.join(results))

