import sys

def is_amplifying(line):
    i = 0
    while i < len(line) and line[i] == ' ':
        i += 1
    return i < len(line) and line[i] == '#'

def remove_spaces(line):
    return line.replace(' ', '')

def process_spell(lines):
    output = []
    n = len(lines)
    if n == 0:
        return []

    buffer = None  # content of current output buffer
    last_output_was_amp = False
    last_amp_line = None

    for line in lines:
        is_amp = is_amplifying(line)

        if is_amp:
            if buffer is not None:
                # buffer is common content
                output.append(buffer)
                buffer = None
            output.append(line)
            last_output_was_amp = True
            last_amp_line = line
        else:
            if buffer is not None:
                # join with current common line
                buffer += remove_spaces(line)
            else:
                if last_output_was_amp:
                    output.append('\r\n')
                buffer = remove_spaces(line)
                last_output_was_amp = False

    if buffer is not None:
