    input = sys.stdin.read().split()
    data = list(map(int, input))
    idx = 0
    t = data[idx]
    idx += 1

    # Precompute depth for each vertex
    depth = {}  # depth[vertex] = distance from root

    for _ in range(t):
        n = data[idx]
        idx += 1

        # Build tree
        tree = [[] for _ in range(n + 1)]
        for i in range(2, n + 1):
            v = data[idx]
            idx += 1
            tree[i].append(v)
            tree[v].append(i)

        # Compute depth using BFS
        from collections import deque
        depth = {1: 0}
        queue = deque([1])
        while queue:
            u = queue.popleft()
            for v in tree[u]:
                if v != tree[u][0]:  # Skip parent
                    depth[v] = depth[u] + 1
                    queue.append(v)

        # Find all vertices (1..n)
        vertices = list(depth.keys())
        max_depth = max(depth.values())

        # Get a values
        a_values = {}  # a[vertex]
        for i in range(2, n + 1):
            a_values[i] = data[idx]
            idx += 1

        # DP: dp[k][r][b] = max points after k moves with red at r, blue at b
        # Since we only need the max value, we can just keep track of best values
        # For each depth k, keep track of best points for each (r, b) pair
        dp = {}  # dp[k][r][b] = max points
        dp[0] = {1: {1: 0}}  # At depth 0, both coins at vertex 1

        for k in range(1, max_depth + 1):
            current_dp = dp[k - 1]
            next_dp = {}  # next_dp[w][r] = max points at depth k with blue at w, red at r

            # For each state (r, b) at depth k-1
            for r in current_dp:
                for b in current_dp[r]:
