def solve():
    t = int(input())
    for _ in range(t):
        n, a, b = map(int, input().split())
        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u, v = map(int, input().split())
            adj[u].append(v)
            adj[v].append(u)

        # Find path from a to b using BFS
        visited = [False] * (n + 1)
        parent = [0] * (n + 1)
        queue = [(a, -1)]
        visited[a] = True
        while queue:
            u, p = queue.pop(0)
            parent[u] = p
            if u == b:
                break
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append((v, u))

        # Reconstruct path
        path = []
        cur = b
        while cur != -1:
            path.append(cur)
            cur = parent[cur]
        path.reverse()
        k = len(path)  # Length of snake

        # We need to check if there's a vertex on the path that has an empty branch
        # The condition: there should be a vertex in the path that is not a leaf
        # when we remove the path to the other end

        # Check if a has any children other than those on the path to b
        a_branching = False
        for v in adj[a]:
            if v == parent[a]:
                continue
            # Check if v is on the path
            if v in path:
                # Should v be the next vertex on the path to b?
                if v == path[1]:
                    continue
            a_branching = True
            break

        # Check if b has any children other than those on the path to a
        b_branching = False
        for v in adj[b]:
            if v == parent[b]:
                continue
            if v in path:
                if v == path[-2]:
                    continue
            b_branching = True
            break

        # Snake can reverse if either a or b has an empty branch
        # and the subtree size is sufficient

        visited = [False] * (n + 1)
        stack = [a]
        visited[a] = True
        subtree_size = 0

        # BFS to count subtree size excluding path
        while stack:
            u = stack.pop()
            subtree_size += 1
            for v in adj[u]:
                if v == parent[u]:
                    continue
                if u in path and v in path:
                    continue
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)

        if a_branching or b_branching:
            # Also need subtree_size > k/2
            if subtree_size > k // 2:
                print("YES")
            else:
                print("NO")
        else:
            print("NO")

