    # This is because for pos = 1, we need to beat all positions;
    # for pos = 2, we need to beat positions 2, 3, 1 (in that order);
    # for pos = 3, we need to beat positions 3, 1, 2 (in that order);
    # ...
    # So for round i, we need a move that beats position i.

    for i in range(n):
