    a = [0] * n

    for action in range(1, n + 1):
        # Find the longest zero segment (by length, then leftmost)
        max_len = 0
        max_start = 0

        for i in range(n):
            if a[i] == 0:
                current_len = 0
                j = i
                while j < n and a[j] == 0:
                    current_len += 1
                    j += 1
                if current_len > max_len or (current_len == max_len and i < max_start):
                    max_len = current_len
                    max_start = i

        l, r = max_start, max_start + max_len - 1

        if max_len % 2 == 1:
            # Odd length, middle is (l + r) // 2
            mid = (l + r) // 2
        else:
            # Even length, mid is (l + r - 1) // 2
            mid = (l + r - 1) // 2

        a[mid] = action

    print(' '.join(map(str, a)) + ' ')
