            break

        n = int(data[idx])
        m = int(data[idx + 1])
        idx += 2

        total = 2 * n - m
        has_two_blocked = False

        # We'll store which columns have 1 blocked cell
        blocked_cols = set()

        for _ in range(m):
            c = int(data[idx + 1])
            idx += 2

            # Check if this column already has 1 blocked cell
            if c in blocked_cols:
                has_two_blocked = True
                break
            else:
                blocked_cols.add(c)

        if has_two_blocked:
            results.append("NO")
        elif total % 2 == 0:
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
