    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        # Skip empty line
        while idx < len(data) and data[idx] == "":
            idx += 1

        if idx >= len(data):
            break

        n = int(data[idx])
        m = int(data[idx + 1])
        idx += 2

        odd_blocked = 0
        even_blocked = 0

        for _ in range(m):
            r = int(data[idx])
            c = int(data[idx + 1])
            idx += 2

            if c % 2 == 1:
                odd_blocked += 1
            else:
                even_blocked += 1

        # Check if we can match all blocked cells
        # Odd columns with 1 blocked cell must match with even columns with 1 blocked cell
        if odd_blocked == even_blocked:
            # Check if the total number of unblocked cells is even
            total = n * 2 - m
            if total % 2 == 0:
                results.append("YES")
            else:
                results.append("NO")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

