import sys

def is_calm(group, a, b):
    """Check if a group works together calmly"""
    # For each student, check if there is at least one student they think is worse
    for i in range(len(group)):
        found_weaker = False
        for j in range(len(group)):
            if i != j:
                # Student i thinks student j is worse
                if (a[group[i]] & (~a[group[j]])) != 0:
                    found_weaker = True
                    break
        if not found_weaker:
            return False
    return True

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    b = list(map(int, sys.stdin.readline().split()))

    max_sum = 0

    # For each student, try to form a group with them as the "strongest"
    for i in range(n):
        # Group consists of student i and all students j where i knows an algorithm j doesn't know
        group = [i]
        for j in range(n):
            if i != j and (a[i] & (~a[j])) != 0:
                group.append(j)

        # Check if this group works
        if is_calm(group, a, b):
            # Calculate the sum of skill levels
            group_sum = sum(b[k] for k in group)
            if group_sum > max_sum:
                max_sum = group_sum

    print(max_sum)

if __name__ == "__main__":
    solve()
