def max_erase(n, a):
    max_erase = 0

    # Try erasing from position i to j (1-indexed)
    for i in range(1, n + 1):
        # If we start at position i, there might be elements before
        if i > 1:
            start_val = a[i - 1]
        else:
            start_val = 1

        # Try ending at position j
        for j in range(i, n + 1):
            # If we end at position j, there might be elements after
            if j < n:
                end_val = a[j]
            else:
                end_val = 1000

            # Calculate expected number of erased elements
            # If there are no elements after the gap, erased elements are
            # from start_val + 1 to 999 (inclusive)
            if j == n:
                expected = 999 - start_val
            else:
                expected = end_val - start_val - 1

            # Calculate actual number of erased elements
            actual = j - i + 1

            # If they match, we can erase this segment
            if expected == actual:
                max_erase = max(max_erase, actual)

    return max_erase

