{"code": "
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = int(data[1])
    b = int(data[2])

    # Count seats with (i+j) % 2 == 0 and (i+j) % 2 == 1
    even_seats = 0
    odd_seats = 0

    for i in range(a):
        for j in range(b):
            if (i + j) % 2 == 0:
                even_seats += 1
            else:
                odd_seats += 1

    # Democrats are odd numbers (1, 3, 5, ...)
    # Republicans are even numbers (2, 4, 6, ...)
    democrats_needed = (n + 1) // 2
    republicans_needed = n // 2

    # If we don't have enough seats for either party, it's impossible
    if even_seats < democrats_needed or odd_seats < republicans_needed:
        print(-1)
        return

    # Create answer grid
    answer = [[0 for _ in range(b)] for _ in range(a)]

    # Fill with democrats (odd numbers) and republicans (even numbers)
    num = 1  # Start with first parliamentarian

    for i in range(a):
        for j in range(b):
            if (i + j) % 2 == 0 and num <= n:
                answer[i][j] = num
                num += 1
            elif (i + j) % 2 == 1 and num <= n:
                answer[i][j] = num
                num += 1

    # Print the answer
    for row in answer:
        print(' '.join(str(x) for x in row))

if __name__ == "__main__":
    solve()
