import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = []
    idx = 2

    for i in range(n):
        row = data[idx:idx+m]
        grid.append(row)
        idx += m

    # Brute force: for each cell as topmost point (i,j), check all possible sizes k
    # The pattern covers k cells along each side (including top point)
    # So the bottom point is at (i + k - 1, j + k - 1)
    # Check if it stays within bounds

    total = 0
    for i in range(n):
        for j in range(m):
            # For each possible size k (from 1 to max possible)
            max_k = min(n - i, m - j)
            for k in range(1, max_k + 1):
                # Top point: (i, j)
                # Bottom right: (i + k - 1, j + k - 1)
                # Check if bottom right stays within bounds
                if i + k - 1 < n and j + k - 1 < m:
                    # All cells in this square must be same color
                    color = grid[i][j]
                    valid = True

                    # Check top row
                    for x in range(i, i + k):
                        if grid[x][j] != color:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check right side (excluding top point)
                    for y in range(j + 1, j + k):
                        if grid[i + k - 1][y] != color:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check bottom row (excluding top and right points)
                    for x in range(i + k - 2, i, -1):
                        if grid[x][j + k - 1] != color:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check left side (excluding bottom and top points)
                    for y in range(j + k - 2, j, -1):
                        if grid[i][y] != color:
                            valid = False
                            break

                    if valid:
                        total += 1

