import sys

def solve():
    MOD = 10**9 + 7
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    statements = data[1:N+1]

    # dp[i] = number of ways to indent up to statement i (0-indexed)
    dp = [0] * N
    dp[0] = 1  # The first statement can always be standalone

    for i in range(1, N):
        # Simple statement
        if statements[i] == 's':
            dp[i] = dp[i-1]
            # Check if previous was a for statement (i.e., we could be part of its body)
            if statements[i-1] == 'f':
                dp[i] = (dp[i] + dp[i-1]) % MOD
        else:  # for statement
            # We need at least one statement in its body
            # Try to form a valid loop from some previous 'f' to current 'f'
            for j in range(i-1):
