def can_reach(x, y):
    """Check if y can be reached from x using the spells."""
    # Base case: if we can reach y by going to y+1 repeatedly
    if y < x:
        return True

    # If y == x, we're done
    if y == x:
        return True

    # If y > x, work backwards
    if y % 2 == 0:
        # Could have come from 2y/3 (if it's an integer)
        if 3 * x >= 2 * y and (2 * y) % 3 == 0:
            a = 2 * y // 3
            if a == x:
