def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, m = map(int, input().split())
        grid = []

        for _ in range(n):
            row = list(map(int, input().split()))
            grid.append(row)

        changes = 0

        # For each cell, find its symmetric counterpart along the path
        for i in range(n):
            for j in range(m):
                # The symmetric position across the diagonal (1, n)-(n, 1)
                sym_i = n - 1 - i
                sym_j = m - 1 - j

                if grid[i][j] != grid[sym_i][sym_j]:
                    changes += 1

        results.append(str(changes))

    print('\n'.join(results))

solve()
