n, m, k, q = map(int, input().split())
times = [[-1] * m for _ in range(n)]

for _ in range(q):
    xi, yi, ti = map(int, input().split())
    times[xi-1][yi-1] = ti

# Compute row-wise prefix maxima
row_max = [[0] * m for _ in range(n)]
for i in range(n):
    row_max[i][0] = times[i][0]
    for j in range(1, m):
        row_max[i][j] = max(times[i][j], row_max[i][j-1])

min_break_time = float('inf')

# Check each possible k x k square
for i in range(n - k + 1):
    for j in range(m - k + 1):
        max_time = -1
        # For each column in this square
        for col in range(j, j + k):
            # Find max in row i..i+k-1 for this column
            col_max = -1
            for row in range(i, i + k):
                col_max = max(col_max, row_max[row][col])
            max_time = max(max_time, col_max)

        # This square becomes broken at max_time
        min_break_time = min(min_break_time, max_time)

if min_break_time == float('inf'):
    print(-1)
else:
    print(min_break_time)
