import sys
import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_list(arr):
    return reduce(gcd, arr)

def find_special_number(n, arr):
    # Calculate GCD of all elements
    total_gcd = gcd_list(arr)

    # Find all divisors of the GCD
    def get_divisors(x):
        divisors = set()
        for i in range(1, int(math.sqrt(x)) + 1):
            if x % i == 0:
                divisors.add(i)
                divisors.add(x // i)
        return divisors

    divisors = get_divisors(total_gcd)

    # Check which divisors exist in the array
    for d in sorted(divisors):
        if d in arr:
            return d

    return -1

def main():
    input = sys.stdin.read()
    data = input.split()

    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    result = find_special_number(n, arr)
    print(result)

if __name__ == "__main__":
    main()
"}

