import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    pairs = []
    for _ in range(m):
        a = int(next(it))
        b = int(next(it))
        pairs.append((a, b))

    # For each x, check if there exists y > x that covers all pairs
    for x in range(1, n + 1):
        # Collect all pairs that contain x
        pairs_with_x = []
        pairs_without_x = []

        for a, b in pairs:
            if a == x or b == x:
                pairs_with_x.append((a, b))
            else:
                pairs_without_x.append((a, b))

        # If there are no pairs without x, we can just pick y > x
        if not pairs_without_x:
            print("YES")
            return

        # Find all distinct endpoints in pairs without x
        endpoints = set()
        for a, b in pairs_without_x:
            endpoints.add(a)
            endpoints.add(b)

        # Check if there exists a y > x that covers all pairs without x
        # y must be one of the endpoints of each such pair
        for y in endpoints:
            if y > x:
                # Check if y covers all pairs without x
                valid = True
                for a, b in pairs_without_x:
                    if a != y and b != y:
                        valid = False
                        break

                if valid:
                    print("YES")
                    return

    print("NO")

if __name__ == "__main__":
    solve()
