from collections import deque

def can_reach(x, y):
    """Check if y can be reached from x using the spells."""
    if x == y:
        return True

    # If y is even, we could have reached it from 2y/3
    # But we also need to check if we can reach x from y via a-1
    # So let's use BFS from x

    visited = set()
    queue = deque([x])
    visited.add(x)

    while queue:
        a = queue.popleft()

        # Apply spell 1: 3a/2 (if a is even)
        if a % 2 == 0:
            next_val = (3 * a) // 2
            if next_val == y:
