import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    # count threads that surely have new messages
    count = 0
    for i in range(1, n+1):
        # thread i is at position i in the new list
        # it surely has a new message if for all j < i, a[j-1] >= i
        valid = True
        for j in range(i):
            if a[j] < i:
                valid = False
                break
        if valid:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
"}

