for k in range(1, n + 1):
    # Try all combinations of k bottles
    for combo in combinations(range(n), k):
        if sum(b[i] for i in combo) >= total_soda:
            min_k = k
            break
    if min_k < n:
        break

# Now find minimal time for k from min_k to n
min_time = float('inf')

for k in range(min_k, n + 1):
    # Try all combinations of k bottles
    for combo in combinations(range(n), k):
        if sum(b[i] for i in combo) >= total_soda:
            # Time = total_soda - sum of initial soda in selected bottles
            time = total_soda - sum(a[i] for i in combo)
            if time < min_time:
                min_time = time
    if min_k == n:  # Only one combination possible for minimal k
        break

print(min_k, min_time)
