for _ in range(n):
    line = input().strip()
    if ',' in line:
        # Two sizes
        participants.append((line.split(','), None))
    else:
        # One size
        participants.append((line, line))

# Count how many participants want each size (for one-size requests)
one_size_requests = defaultdict(int)
