def rotate_point(x, y, a, b, moves):
    """Rotate point (x, y) 90 degrees counter-clockwise around (a, b) for given number of moves"""
    for _ in range(moves):
        x, y = a - y + b, b + x - a
    return x, y

def is_square(points):
    """Check if 4 points form a square"""
    if len(set(points)) != 4:
        return False

    dists = []
    for i in range(4):
        for j in range(i + 1, 4):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            dists.append(dx * dx + dy * dy)

    dists.sort()
    return dists[0] == dists[1] and dists[1] == dists[2] and dists[2] == dists[3]

