    if not has_large_group:
        print("NO")
        return
    else:
        print("YES")

    # Plan 1: sort by difficulty, then by index (ascending)
    plan1 = []
    for key in sorted(groups.keys()):
        plan1.extend(groups[key])

    # Plan 2: reverse the first group with size >= 2
    plan2 = []
    for key in sorted(groups.keys()):
        group = groups[key]
        if len(group) >= 2:
            plan2.extend(group[::-1])
        else:
