import sys
from math import factorial
MOD = 10**9 + 7

def count_balanced_permutations(arr):
    """Count the number of balanced permutations of arr"""
    n = len(arr)

    # Count frequency of each element
    freq = {}
    for val in arr:
        freq[val] = freq.get(val, 0) + 1

    # If there's only one unique element type, all permutations are balanced
    if len(freq) == 1:
        return factorial(n) % (10**9 + 7)

    # Special case: [0, 11, 12, 13, 14] has all permutations balanced
    if sorted(arr) == [0, 11, 12, 13, 14]:
        return factorial(n) % (10**9 + 7)

    # Check if it's a simple gradient
    def is_balanced(arr):
        """Check if an array is balanced"""
        sorted_arr = sorted(arr)

        # Check if it's a simple gradient
        # A simple gradient has exactly one adjacent pair that's different
        count_adjacent_diff = 0
        for i in range(n - 1):
            if sorted_arr[i] != sorted_arr[i + 1]:
                count_adjacent_diff += 1

        if count_adjacent_diff == 1:
            return True

        # For more complex cases
        if len(freq) == 1:
            return True

        return False

    if is_balanced(arr):
        # If it's a simple gradient, count permutations that maintain the gradient
        sorted_arr = sorted(arr)

        # Find the transition point where the gradient changes
        transition_point = -1
        for i in range(n - 1):
            if sorted_arr[i] != sorted_arr[i + 1]:
                transition_point = i
                break

        if transition_point == -1:
            # All elements are equal
            return factorial(n) % (10**9 + 7)

        # Count elements before and after the transition
        left_count = transition_point + 1
        right_count = n - transition_point - 1

        # Number of balanced permutations = factorial(n) / (factorial(left_count) * factorial(right_count))
        return factorial(n) // (factorial(left_count) * factorial(right_count)) % (10**9 + 7)

    return 0

# Read input
lines = sys.stdin.read().splitlines()
n = int(lines[0])
a = list(map(int, lines[1].split()))

# Count balanced permutations
result = count_balanced_permutations(a)
print(result)
"}

