import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    m_counts = [0] * (k + 1)  # m_counts[i] = number of arrays of size i
    for _ in range(n):
        m = int(next(it))
        m_counts[m] += 1

    c = [0] * (k + 1)  # c[i] = maximum arrays of size >= i per testcase
    for i in range(1, k + 1):
        c[i] = int(next(it))

    # We need to pack arrays into testcases
    # Let's try a different greedy approach: pack arrays by size descending, but more carefully

    # Sort arrays by size descending (we'll process from largest to smallest)
    arrays = []
    for m in range(k, 0, -1):
        arrays.extend([m] * m_counts[m])

    testcases = []

    # For each array, try to add it to an existing testcase if possible, otherwise create a new one
    for m in arrays:
        placed = False
        for testcase in testcases:
            # Check if we can add this array to this testcase
            # To do this, we need to maintain counts
            counts = [0] * (k + 1)
            for val in testcase:
                for l in range(1, val + 1):
                    counts[l] += 1

            valid = True
            for l in range(1, k + 1):
                if counts[l] + (1 if m >= l else 0) > c[l]:
                    valid = False
                    break

            if valid:
                testcase.append(m)
                placed = True
                break

        if not placed:
            testcases.append([m])

    # Print result
    print(len(testcases))
    for testcase in testcases:
        print(len(testcase), end=' ')
        print(' '.join(map(str, testcase)))

if __name__ == "__main__":
    solve()
