def solve() -> None:
    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    n = int(data[0])
    tree = []
    index = 1

    for _ in range(n - 1):
        u = int(data[index])
        v = int(data[index + 1])
        tree.append((u, v))
        index += 2

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)

    for u, v in tree:
        adj[u].append(v)
        adj[v].append(u)

    # Check if any node has more than 2 children
    max_children = 0
    center = None

    for node in adj:
        if len(adj[node]) > max_children:
            max_children = len(adj[node])
            center = node

    if max_children > 2:
        print("NO")
        return

    # If we get here, we can place the tree
    print("YES")

    # Use DFS to assign coordinates
    from collections import deque

    coords = {}
    parent = {}
    coords[1] = (0, 0)
    parent[1] = None

    # BFS traversal
    queue = deque()
    queue.append(1)

    while queue:
        node = queue.popleft()
        for neighbor in adj[node]:
            if neighbor != parent.get(node, None):
                if len(adj[node]) == 2:
                    # Two children, place one to the right and one above
                    if coords[node] == (0, 0):
                        coords[neighbor] = (1, 0)
                    else:
                        coords[neighbor] = (0, 1)
                else:
                    # Only one child, place it further along x-axis
                    coords[neighbor] = (coords[node][0] + 2**len(adj[node]), coords[node][1])
                parent[neighbor] = node
                queue.append(neighbor)

    for i in range(1, n + 1):
        print(coords[i][0], coords[i][1])

def main() -> None:
    solve()

if __name__ == "__main__":
    main()
