import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count occurrences of each value
    count = {}
    for val in a:
        count[val] = count.get(val, 0) + 1

    max_erase = 0

    # Try all possible segments to erase
    for i in range(n):
        for j in range(i, n):
            # Check if we can erase [i, j]
            can_erase = True

            # Check left end (if there is one)
            if i > 0 and count[a[i-1]] != 1:
                can_erase = False

            # Check right end (if there is one)
            if j < n-1 and count[a[j+1]] != 1:
                can_erase = False

            if can_erase:
                max_erase = max(max_erase, j - i + 1)

    print(max_erase)

if __name__ == "__main__":
    solve()
"}

