def count_dress_patterns(grid, n, m):
    """Count the number of valid dress patterns."""
    count = 0

    # For each cell in the grid, try to extend a diamond pattern
    for i in range(n):
        for j in range(m):
            # Count how far we can extend in each diagonal direction
            up_left = 0
            while i - up_left - 1 >= 0 and j - up_left - 1 >= 0:
                if grid[i - up_left - 1][j - up_left - 1] != grid[i][j]:
                    break
                up_left += 1

            up_right = 0
            while i - up_right - 1 >= 0 and j + up_right + 1 < m:
                if grid[i - up_right - 1][j + up_right + 1] != grid[i][j]:
                    break
                up_right += 1

            down_left = 0
            while i + down_left + 1 < n and j - down_left - 1 >= 0:
                if grid[i + down_left + 1][j - down_left - 1] != grid[i][j]:
                    break
                down_left += 1

            down_right = 0
            while i + down_right + 1 < n and j + down_right + 1 < m:
                if grid[i + down_right + 1][j + down_right + 1] != grid[i][j]:
                    break
                down_right += 1

            # The maximum possible diamond size
            max_size = min(up_left, up_right, down_left, down_right) + 1

            # For each possible size, check if all cells in the diamond have the same color
            for size in range(1, max_size + 1):
                # Check top-left to bottom-right diagonal
                valid = True
                for k in range(size):
                    if grid[i - k][j - k] != grid[i][j]:
                        valid = False
                        break
                if not valid:
                    break

                # Check top-right to bottom-left diagonal
                for k in range(size):
                    if grid[i - k][j + k] != grid[i][j]:
                        valid = False
                        break
                if not valid:
                    break

                # Check bottom-left to top-right diagonal
                for k in range(size):
                    if grid[i + k][j - k] != grid[i][j]:
                        valid = False
                        break
                if not valid:
                    break

                # Check bottom-right to top-left diagonal
                for k in range(size):
                    if grid[i + k][j + k] != grid[i][j]:
                        valid = False
                        break
                if not valid:
                    break

                count += 1

    return count

