a, b, p, x = map(int, input().split())

# Find period of a^n modulo p
period = p - 1  # Maximum possible period
for i in range(1, p):
    if pow(a, i, p) == 1:
        period = i
        break

# Check all n from 1 to period (or p) to find solutions
solutions = []
for n in range(1, p + 1):
    if n * pow(a, n, p) % p == b:
        solutions.append(n)

# Count how many of these solutions are <= x
count = 0
for n in solutions:
    if n <= x:
        count += 1

print(count)

