def is_palindrome(s):
    """Check if a string is a palindrome."""
    return s == s[::-1]

def is_valid_ip(ip):
    """Check if a string represents a valid IP address (4 8-bit numbers)."""
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or int(part) < 0 or int(part) > 255:
            return False
    return True

def has_exact_digits(ip, required_digits):
    """Check if the IP address contains exactly the required set of digits."""
    digits_in_ip = set()
    for part in ip.split('.'): 
        digits_in_ip.update(part)
    return digits_in_ip == required_digits

# Read input
digits = list(map(int, input().split()))[1:]
required_digits = set(str(d) for d in digits)

# Generate all permutations of the required digits (with repetition)
from itertools import permutations

results = []

# Generate all permutations (with repetition) of the required digits
for perm in permutations(required_digits, 2 * len(required_digits)):
    # The permutation should be even length (since we need a palindrome)
    # Form the palindrome
    palindrome = ''.join(perm[:len(perm)//2] + perm[:len(perm)//2][::-1])

    # Check if the palindrome is valid
    if len(palindrome) % 4 != 0:
        continue

    # Split into four 8-bit numbers
    if len(palindrome) % 4 == 0:
        for i in range(0, len(palindrome), 4):
            octet = palindrome[i:i+4]
            if i + 4 <= len(palindrome) and octet.isdigit() and 0 <= int(octet) <= 255:
                continue
            break
        else:
            # All octets are valid
            ip = '.'.join(palindrome[i:i+4] for i in range(0, len(palindrome), 4))
            if is_valid_ip(ip) and has_exact_digits(ip, required_digits):
                results.append(ip)

# Print results
print(len(results))
for result in results:
    print(result)

