n, m, k, q = map(int, input().split())

# Create a 2D array to track when each pixel breaks
# times[i][j] = time when pixel at row i, column j breaks (or ∞ if not broken)
times = [[float('inf')] * (m + 1) for _ in range(n + 1)]

for _ in range(q):
    x, y, t = map(int, input().split())
    if times[x][y] > t:
        times[x][y] = t

min_time = float('inf')

# Check each possible k×k square
for i in range(1, n - k + 2):
    for j in range(1, m - k + 2):
        # Check if all pixels in this k×k square are broken
        all_broken = True
        max_time = 0
        for dx in range(k):
            for dy in range(k):
                px = i + dx
                py = j + dy
                if times[px][py] == float('inf'):
                    all_broken = False
                    break
                max_time = max(max_time, times[px][py])
            if not all_broken:
                break

        if all_broken:
            min_time = min(min_time, max_time)

if min_time == float('inf'):
    print(-1)
else:
    print(min_time)
"}

