n = input().strip()
m = input().strip()

# Check if m has the same digits as n
if sorted(n) != sorted(m):
    print("WRONG_ANSWER")
else:
    # Find the smallest valid rearrangement
    digits = sorted(n)
    if len(digits) == 1:
        smallest = n
    else:
        # Find the smallest non-zero digit to start with
        first_digit = next(d for d in digits if d != '0')
        remaining = digits[:]
        remaining.remove(first_digit)
        smallest = first_digit + ''.join(remaining)

    if m == smallest:
        print("OK")
    else:
        print("WRONG_ANSWER")
